{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Background The following systematic review explores the uses and understandings of physical, human-to-human touch engagements in healthcare professions. Given its central importance as both a diagnostic tool and a form of non-verbal communication, this review sought to understand the communicative, social and affective dimensions of touches a part of healthcare, medical or nursing interventions. We attempt to understand how touch communication seems to be structured in the literature, and what tends to be communicated via touch, but also to highlight how the dogmatic distinction between 'instrumental' and 'expressive' touches might have obscured a socio-affective matrix within all touches.",
      "reason": "Describes aspects of the existing literature (e.g., instrumental vs expressive distinction) that may have obscured understanding, but does not clearly identify important uncertainties or gaps in knowledge beyond this framing."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Given its central importance as both a diagnostic tool and a form of non-verbal communication, this review sought to understand the communicative, social and affective dimensions of touches a part of healthcare, medical or nursing interventions.",
      "reason": "Provides an explicit rationale for conducting the review by linking the topic’s importance to the need to understand communicative/social/affective dimensions."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "In light of this brief background analysis, the present review sets itself apart from previous ones by attempting to understand the communicative, social and affective dimensions of touch in healthcare and nursing professions, in both its instrumental and expressive instances.",
      "reason": "States the review differentiates itself from previous reviews, but the evidence does not show a clear, cited explanation of why a new review is needed in light of specific existing systematic reviews (e.g., updates/replications with citations)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not indicate this is a review of intervention effects, and it does not report a proposed mechanism of action for an intervention."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not describe a complex intervention or delivery context in a way that would require a logic model, and no logic model is reported."
    }
  ],
  "confidence": 58
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "This systematic review thus seeks to highlight this communicative value of touch within healthcare professions, identifying the role and value that touch plays in patient-practitioner communication, as well as identifying further open questions requiring further investigation.",
      "reason": "The review provides an explicit statement of its objective(s)/aim(s) in the Introduction (seeking to highlight communicative value, identify role/value in patient–practitioner communication, and identify open questions)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_8",
      "quote": "The present review is exploratory in nature: for this reason, studies from all years and in any language spoken by the team (i.e. English, Italian, French, Spanish, Finnish) were included",
      "reason": "The evidence indicates the review is exploratory rather than an intervention-effects review with planned comparative effects; therefore the conditional requirement to state planned comparisons using PICO (or variant) does not apply."
    }
  ],
  "confidence": 74
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "A PICo (Population, Interest, Context) framework ([45]; see also: [46]) was used to formulate the preliminary question 'What are care-givers' (i.e. allied health professionals, nurses, doctors, carers) [Population] actual uses and experiences of touch [Interest] when providing real and direct medical care to patients [Context]?' . From this question, PICo was also used to devise inclusion and exclusion criteria and to inform an initial set of search terms.",
      "reason": "The review specifies key eligibility components via PICo (Population, Interest, Context) and uses them to devise inclusion/exclusion criteria, but the evidence provided does not report other required study-characteristic components such as eligible study designs/settings/follow-up requirements."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "for this reason, studies from all years and in any language spoken by the team (i.e. English, Italian, French, Spanish, Finnish) were included ('Language' exclusion criterion).",
      "reason": "Eligibility for report characteristics is partially specified (language inclusion/exclusion is described, and “all years” is stated). However, the evidence does not specify dissemination year details beyond “all years,” nor does it state publication/report status requirements."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not describe how the review distinguishes exclusions due to outcomes not being measured versus outcomes not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not specify groups used in each synthesis or link those groups to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Two of them ('language' and 'non-empirical') were based on the team expertise and the general aim of this review (i.e. capturing empirical social analysis over anecdotal case studies or philosophical discussions), while the other 8 were formulated starting from the PICo framework.",
      "reason": "The review provides rationales for notable restrictions on eligibility criteria (e.g., language and non-empirical decisions based on team expertise/aim, and other criteria based on the PICo framework)."
    }
  ],
  "confidence": 62
}

